<?php declare(strict_types=1); namespace ProcessWire;
require __DIR__.'/support/bootstrap.php';
[$m,$db,$a,$b,$c]=fixture();$operator=new class(99)extends User{public function isSuperuser(){return true;}};
check(!$m->mentionsReady(),'uninstalled mentions unavailable without DDL');check((int)$db->query("SELECT COUNT(*) FROM sqlite_master WHERE name LIKE 'messenger_mention%'")->fetchColumn()===0,'readiness never installs optional schema');denied(fn()=>$m->installGroupMentions($a));
$m->installGroups($operator);$m->set('groups_enabled',1)->set('first_contact_mode','open')->set('max_messages_minute',1000)->set('edit_window_minutes',60);$g=$m->createGroup($a,'Mentions',[$b->id,$c->id],'mention_group_fixture01');$gid=$g['id'];$m->respondGroupInvitation($gid,$b,true);$m->installGroupMentions($operator);check($m->mentionsReady(),'explicit admin migration');
$mode=$m->setGroupMentionMode($b,$gid,true);check($mode===['id'=>$gid,'mentions_only'=>true],'member controls own exact notification mode');check($m->groupDetails($gid,$b)['mentions_only']&&!$m->groupDetails($gid,$a)['mentions_only'],'notification mode is private per member');denied(fn()=>$m->setGroupMentionMode($c,$gid,true));
$plain=$m->sendMessage($gid,$a,'Regular message','mention_plain_fixture01');$hit=$m->sendMessage($gid,$a,'Hello @fixture-22, join us','mention_hit_fixture001');$miss=$m->sendMessage($gid,$a,'mail@fixture-22 and @fixture-220 and @fixture-33','mention_miss_fixture01');
$rows=$m->conversationMessages($gid,$b);$by=array_column($rows,null,'id');check($by[$hit['id']]['mentioned']&&$by[$hit['id']]['mentions'][0]['name']==='fixture-22','eligible exact token mentions current member');check(!$by[$miss['id']]['mentioned']&&$by[$miss['id']]['mentions']===[],'email, substring and pending invite do not mention anyone');check(!$by[$plain['id']]['mentioned'],'ordinary text never becomes a mention');$snapshot=$m->groupDetails($gid,$b);check($snapshot['last_message']['id']===$miss['id']&&$snapshot['last_mention']['id']===$hit['id'],'a later ordinary message never masks own unread mention');
$q=$db->prepare('SELECT username FROM messenger_mentions WHERE message_id=?');$q->execute([$hit['id']]);check(str_starts_with($q->fetchColumn(),'menc:v1:'),'mention username is authenticated encrypted at rest');
$allowed=new \ReflectionMethod($m,'mentionNotificationAllowed');check(!$allowed->invoke($m,$plain['id'],$b->id)&&$allowed->invoke($m,$hit['id'],$b->id),'mentions-only filters ordinary notifications');check($allowed->invoke($m,$plain['id'],$a->id),'ordinary per-member mode remains all');
$list=$m->groupMentions($b,$gid);check(array_column($list['items'],'id')===[$hit['id']]&&$list['next_before']===null,'own mention navigation page');check($m->groupMentions($a,$gid)['items']===[],'cannot read another members mention feed');denied(fn()=>$m->groupMentions($c,$gid));
$m->editMessage($hit['id'],$a,'Mention removed');check($m->groupMentions($b,$gid)['items']===[]&&!$allowed->invoke($m,$hit['id'],$b->id),'editing away mention updates feed and pending delivery filter');$m->editMessage($plain['id'],$a,'Edited @FIXTURE-22');check($m->groupMentions($b,$gid)['items'][0]['id']===$plain['id'],'case-insensitive username token supports edits');
$m->hideMessage($plain['id'],$b);check($m->groupMentions($b,$gid)['items']===[],'hidden mentions stay hidden');check($m->groupDetails($gid,$b)['last_mention']===null,'hidden and edited-away mentions cannot remain in alert preview');
$before=$m->sendMessage($gid,$a,'Pending @fixture-33','mention_history_before');$m->respondGroupInvitation($gid,$c,true);check($m->groupMentions($c,$gid)['items']===[],'joining cannot reveal old mention/history');$after=$m->sendMessage($gid,$a,'Hello @fixture-33','mention_history_after1');check($m->groupMentions($c,$gid)['items'][0]['id']===$after['id'],'new member receives subsequent mentions');
$m->deleteMessage($after['id'],$a);check((int)$db->query('SELECT COUNT(*) FROM messenger_mentions WHERE message_id='.(int)$after['id'])->fetchColumn()===0,'global message deletion erases mention identifiers');
$exp=$m->sendMessage($gid,$a,'Expires @fixture-22','mention_expiry_fixture');$db->prepare('UPDATE messenger_messages SET expires_at=? WHERE id=?')->execute([time()-1,$exp['id']]);check($m->groupMentions($b,$gid)['items']===[],'expired mention cannot appear in navigation');
$quote=$m->sendMessage($gid,$a,"> Alice\n> Quoted @fixture-22\n\nNo new mention",'mention_quote_fixture1');check(!$allowed->invoke($m,$quote['id'],$b->id),'reply quotations do not generate implicit mentions');
$punctuation=$m->sendMessage($gid,$a,'Hello @fixture-22.','mention_punctuation01');check($allowed->invoke($m,$punctuation['id'],$b->id),'sentence-ending period is handled without substring matching');
$m->setMuted($gid,$b,date('Y-m-d H:i:s',time()+3600));$m->setGroupMentionMode($b,$gid,false);check($m->groupDetails($gid,$b)['muted'],'changing mention filter never unmutes a chat');$m->setGroupMentionMode($b,$gid,true);
$m->changeGroup($gid,$a,'remove',['user_id'=>$b->id]);denied(fn()=>$m->groupMentions($b,$gid));denied(fn()=>$m->setGroupMentionMode($b,$gid,false));
check(!$db->inTransaction(),'failed mention operations do not leak a transaction');
// Bounded descending navigation has no duplicates across gaps/pages.
[$m,$db,$a,$b]=fixture();$m->installGroups($operator);$m->set('groups_enabled',1)->set('first_contact_mode','open')->set('max_messages_minute',1000);$m->installGroupMentions($operator);$g=$m->createGroup($a,'Pages',[$b->id],'mention_pages_group01');$gid=$g['id'];$m->respondGroupInvitation($gid,$b,true);
for($i=0;$i<35;$i++)$m->sendMessage($gid,$a,'Page @fixture-22 '.$i,'mention_page_'.str_pad((string)$i,16,'0',STR_PAD_LEFT));
$first=$m->groupMentions($b,$gid);$second=$m->groupMentions($b,$gid,$first['next_before']);check(count($first['items'])===30&&count($second['items'])===5&&$second['next_before']===null,'bounded mention pagination');check(!array_intersect(array_column($first['items'],'id'),array_column($second['items'],'id')),'exclusive cursors never repeat a mention');
for($i=0;$i<60;$i++)$m->setGroupMentionMode($b,$gid,$i%2===0);check($m->setGroupMentionMode($b,$gid,false)['mentions_only']===false,'matching preference retry free at limit');denied(fn()=>$m->setGroupMentionMode($b,$gid,true),'rate_limited');
// Too many recipients is rejected atomically, including the message itself.
[$m,$db,$a]=fixture();$m->installGroups($operator);$m->set('groups_enabled',1)->set('first_contact_mode','open')->set('max_new_recipients_day',1000);$m->installGroupMentions($operator);$ids=range(100,120);$g=$m->createGroup($a,'Bounded',$ids,'mention_bound_group01');foreach($ids as$id)$m->respondGroupInvitation($g['id'],new User($id),true);
try{$m->sendMessage($g['id'],$a,implode(' ',array_map(static fn($id)=>'@fixture-'.$id,$ids)),'mention_bound_write01');throw new \RuntimeException('Unbounded mentions accepted');}catch(\InvalidArgumentException $e){check((int)$db->query('SELECT COUNT(*) FROM messenger_messages')->fetchColumn()===0,'recipient cap rollback leaves no message or side effects');}
echo 'Group mention checks: '.$GLOBALS['checks'].PHP_EOL;
